    border: 'none',
    cursor: 'pointer',
    marginBottom: '20px',
    borderRadius: '5px',
    fontSize: '1rem',
  },
  error: {
    color: 'red',
    marginTop: '20px',
  },
  filterContainer: {
    marginBottom: '20px',
  },
  filterLabel: {
    marginRight: '10px',
    fontSize: '1.1rem',
  },
  filterSelect: {
    padding: '8px',
