  },
  td: {
    padding: '10px',
    borderBottom: '1px solid #ddd',
  },
  tr: {
    backgroundColor: '#fff',
  },
  input: {
    padding: '5px',
    fontSize: '1rem',
    borderRadius: '5px',
    border: '1px solid #ddd',
    width: '100%',
  },
  saveButton: {
    backgroundColor: '#28a745',
    color: 'white',
    border: 'none',
    cursor: 'pointer',
    padding: '8px 15px',
    borderRadius: '5px',
    fontSize: '1rem',
    marginRight: '10px',
  },
  cancelButton: {
    backgroundColor: '#dc3545',
    color: 'white',
