    cursor: 'pointer',
    padding: '8px 15px',
    borderRadius: '5px',
    fontSize: '1rem',
  },
  editButton: {
    backgroundColor: '#ffc107',
    color: 'white',
    border: 'none',
    cursor: 'pointer',
    padding: '8px 15px',
    borderRadius: '5px',
